  "summary": "MongoDB has exited (status: exited), directly breaking the UDR backend and triggering a cascade that demotes P-CSCF, UPF, I-CSCF, S-CSCF, and SMF as downstream reporters; their respective SIP error spikes, GTP traffic drops, and rate shifts are secondary consequences of the UDR/PCF authorization failure.",
  "layer_status": {
    "infrastructure": {
      "rating": "red",
      "evidence": [
        "MongoDB container is exited"
      ],
      "note": "L10: MongoDB is exited, which is the direct fault locus breaking the UDR datastore backend."
    },
    "ran": {
      "rating": "green",
      "evidence": [
        "core.amf.ran_ue = 2",
        "core.amf.gnb = 1"
      ],
      "note": "RAN is healthy and maintaining UE attachments."
    },
    "core": {
      "rating": "yellow",
      "evidence": [
        "normalized.upf.gtp_indatapktn3upf_per_ue:drop",
        "normalized.upf.gtp_outdatapktn3upf_per_ue:drop",
        "normalized.smf.bearers_per_ue:shift"
      ],
      "note": "L03 applies: UPF GTP drops in bucket (0,1) are low-confidence secondary symptoms of VoNR calls failing to establish; SMF bearers shift reflects default-only state."
    },
    "ims": {
      "rating": "yellow",
      "evidence": [
        "derived.pcscf_sip_error_ratio:spike",
        "normalized.icscf.core:rcv_requests_register_per_ue:shift"
      ],
      "note": "P-CSCF is emitting SIP errors (412) because PCF fails N5 authorization, acting as a downstream reporter of the infrastructure outage."
    }
  },
  "hypotheses": [
    {
      "id": "h1",
      "statement": "mongo is the source of the P-CSCF SIP error spike, the UPF GTP data-plane drops, and the shift in SMF bearers.",
      "primary_suspect_nf": "mongo",
      "supporting_events": [],
      "explanatory_fit": 1.0,
      "falsification_probes": [
        "Check mongo container logs and status to confirm it is exited.",
        "Check UDR and PCF logs to verify they are failing to fetch subscriber data.",
        "Check P-CSCF logs to confirm it is rejecting INVITEs with 412 due to PCF N5 authorization failures (pcscf_n5_call_setup branch)."
      ],
      "specificity": "specific"
    }
  ]
}

challenge_result.investigation_instruction:
