      "primary_suspect_nf": "mongo",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check the container status for mongo",
          "expected_if_hypothesis_holds": "mongo container state is exited or restarting",
          "falsifying_observation": "mongo container state is Up/running",
          "conflates_with": []
