        {
          "tool": "query_subscriber",
          "args_hint": "imsi='001011234567895', domain='core'",
          "expected_if_hypothesis_holds": "Timeout or connection error due to MongoDB being down",
          "falsifying_observation": "Returns subscriber record successfully, indicating the database is up and responding",
          "conflates_with": [
            "PyHSS or UDR is down/exited, failing the query before it reaches mongo",
            "Network path between PyHSS/UDR and mongo is partitioned"
          ]
