        {
          "tool": "get_network_status",
          "args_hint": "Check the container status for pyhss and udr (partner probe for query_subscriber)",
          "expected_if_hypothesis_holds": "pyhss and udr containers are Up and healthy, localizing the subscriber query failure to mongo",
          "falsifying_observation": "pyhss or udr is exited, meaning the subscriber query failure is attributable to them rather than mongo",
          "conflates_with": []
        }
      ],
      "notes": "Hypothesis claims mongo has exited. Verified directly via get_network_status and functionally via KB-authored query_subscriber liveness check. The partner probe rules out PyHSS/UDR crashes as the cause of the query_subscriber failure."
